sys_script_include.script:
var SGCeburuDataInactivate = Class.create();
SGCeburuDataInactivate.prototype = {
    updateDestroyedRecords: function(uniqId) {
		// search the sys_object_source table to map the correct unique identifier
		var rec = new GlideRecordSecure('sys_object_source');
		// find this record
		rec.addQuery("name", "SG-Ceburu");
		rec.addQuery("id", uniqId);
		rec.query();

		// this should only be one loop
		while (rec.next()) {
			var ci = new GlideRecordSecure(rec.target_table);
			ci.addQuery("sys_id", rec.target_sys_id);
			ci.query();
			// this should only be one loop as well
			while (ci.next()) {
				gs.info("Marking "+uniqId+" as Non-Operational as it has been destroyed in Ceburu.");
				ci.setValue("operational_status", 2);
				ci.update();
			}
		}
    },

	findUniqId: function(provider, resource) {
		switch(provider) {
		case "aws":
			return "arn";
		default:
			return "id";
		}
	},

	collectOperationalCIs: function() {
		var currOperational = [];
		var rec = new GlideRecordSecure('x_hashi_service_gr_operational_cis');
		// find this record
		rec.addQuery("ci_operational_status", 1);
		rec.query();

		// collect all cis that have operational_status = 1
		while (rec.next()) {
			currOperational.push(String(rec.sos_id));
		}

		var parents = new GlideRecordSecure('x_hashi_service_gr_cmdb_ci_rel');
		// this view shows us parents that have been created with the SG-Ceburu discovery_source
		// we can see here if the parents are still operational, we want to remove their children
		// from being destroyed
		parents.query();

		while (parents.next()) {
			if (parents.ci_operational_status == 1) {
				var index = currOperational.indexOf(String(parents.sos_id));
				if (index > -1) {
					currOperational.splice(index, 1);
				}
			}
		}

		return currOperational;
	},

    type: 'SGCeburuDataInactivate'
};
